using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "PrecisionExchangeAction", menuName = "Data/Battle/Battle Actions/Orion/PrecisionExchange Action")]
public class PrecisionExchangeAction : ChooseDiceAction
{
	[Header("Precision Action")]
	[SerializeField]
	private PrecisionAction precisionAction;

	[Header("Astrium Requirement")]
	[SerializeField]
	private BattleActionWithMinimumAstriumAction precisionExchangeLogicAction;

	public BattleActionWithMinimumAstriumAction PrecisionExchangeLogicAction => precisionExchangeLogicAction;

	public override void ActionSelected(int amount)
	{
		base.ActionSelected(amount);
		precisionAction.ResetVariables();
	}

	public override bool CheckConditionToBeCasted(int actionValue)
	{
		return precisionExchangeLogicAction.CheckAstriumAmount(actionValue);
	}

	public override void CastAmount(int amount, GameObject source)
	{
		precisionAction.DiceSelected(diceList[0]);
		precisionAction.Cast(source);
		precisionExchangeLogicAction.CheckAstriumCost();
	}
}
